public class TicketService(AppDbContext db) : ITicketService
{
    public async Task<IReadOnlyList<Ticket>> ObtenerTodosAsync(CancellationToken ct = default)
        => await db.Tickets.AsNoTracking().OrderBy(t => t.Id).ToListAsync(ct);

    public Task<Ticket?> ObtenerPorIdAsync(int id, CancellationToken ct = default)
        => db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);

    public async Task<Ticket> CrearAsync(string titulo, CancellationToken ct = default)
    {
        var ticket = new Ticket { Titulo = titulo, Resuelto = false };
        db.Tickets.Add(ticket);
        await db.SaveChangesAsync(ct);
        return ticket;
    }

    public async Task<Ticket?> ActualizarAsync(int id, string titulo, bool resuelto, CancellationToken ct = default)
    {
        var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return null;
        ticket.Titulo = titulo;
        ticket.Resuelto = resuelto;
        await db.SaveChangesAsync(ct);
        return ticket;
    }

    public async Task<bool> EliminarAsync(int id, CancellationToken ct = default)
    {
        var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return false;
        db.Tickets.Remove(ticket);
        await db.SaveChangesAsync(ct);
        return true;
    }
}

