using Microsoft.EntityFrameworkCore;
using TicketsApi.Data;
using TicketsApi.DTOs;
using TicketsApi.Models;
namespace TicketsApi.Services;

public class TicketWorkflowService(AppDbContext db) : ITicketWorkflowService
{
    public async Task<ResultadoCreacionTicket> CrearConComentarioAsync(
        CrearTicketCompletoRequest request, CancellationToken ct = default)
    {
        var titulo = request.Titulo?.Trim() ?? "";
        var comentario = request.ComentarioInicial?.Trim() ?? "";
        if (titulo.Length is < 3 or > 200 || comentario.Length is < 3 or > 1000)
            return new(EstadoCreacionTicket.DatosInvalidos);

        if (request.UsuarioId is int uid &&
            !await db.Usuarios.AnyAsync(u => u.Id == uid, ct))
            return new(EstadoCreacionTicket.UsuarioNoEncontrado);

        await using var tx = await db.Database.BeginTransactionAsync(ct);
        var ticket = new Ticket { Titulo = titulo, UsuarioId = request.UsuarioId, Resuelto = false };
        db.Tickets.Add(ticket);
        await db.SaveChangesAsync(ct);
        db.Comentarios.Add(new Comentario { TicketId = ticket.Id, Texto = comentario });
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return new(EstadoCreacionTicket.Creado, ticket.Id);
    }
}

