namespace TicketsApi.Exceptions;

public sealed class GlobalExceptionHandler(
    ILogger<GlobalExceptionHandler> logger, IProblemDetailsService details) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext context, Exception error, CancellationToken ct)
    {
        logger.LogError(error, "Error no controlado. TraceId: {TraceId}", context.TraceIdentifier);
        context.Response.StatusCode = StatusCodes.Status500InternalServerError;
        var problem = new ProblemDetails
        {
            Status = 500, Title = "Error interno del servidor",
            Detail = "No se pudo completar la operación.",
            Instance = context.Request.Path.Value
        };
        problem.Extensions["traceId"] = context.TraceIdentifier;
        var written = await details.TryWriteAsync(new ProblemDetailsContext
        { HttpContext = context, ProblemDetails = problem });
        if (!written) await context.Response.WriteAsJsonAsync(problem, ct);
        return true;
    }
}

